// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface MyPersonnelRecordOut {
  employee_id: number;
  full_name: string;
  emp_number: string;
  designation: string;
  /** Your orientation status (one row while you are active) */
  orientation: OrientationStatusOut[];
  job_descriptions: EmployeeJobDescriptionOut[];
  /** Your signed appraisals: read them, comment and acknowledge */
  appraisals: AppraisalOut[];
  trainings: TrainingRecordOut[];
}

export interface OrientationStatusOut {
  employee_id: number;
  full_name: string;
  emp_number: string;
  designation: string;
  department_name: string | null;
  joined_on: string | null;
  /** joined_on + orientation_due_days */
  due_on: string | null;
  /** The active topics not covered yet */
  missing: string[];
  topics: number;
  done: number;
  complete: boolean;
  overdue: boolean;
  last_on: string | null;
  /** Told the patients' rights and responsibilities (MSDS HRM 133) */
  patient_rights: boolean;
}

export interface EmployeeJobDescriptionOut {
  assignment_id: number;
  employee_id: number;
  full_name: string;
  emp_number: string;
  jd_id: number;
  /** The text as issued: it never changes */
  content: JobDescriptionContentOut;
  issued_on: string;
  issued_by_name: string;
  employee_signed_on: string | null;
  incharge_user_id: number | null;
  incharge_name: string | null;
  incharge_signed_on: string | null;
  status: "Issued" | "Signed" | "Superseded";
  superseded_by: number | null;
  row_version: number;
}

export interface JobDescriptionContentOut {
  title: string;
  department_name: string | null;
  purpose: string;
  responsibilities: string;
  reports_to: string | null;
  qualifications: string | null;
  appraisal_criteria: string;
  /** The staff rights statement printed with it (MSDS HRM 132 ii) */
  staff_rights: string;
}

export interface AppraisalOut {
  appraisal_id: number;
  appraisal_number: string;
  employee_id: number;
  full_name: string;
  emp_number: string;
  designation: string;
  department_name: string | null;
  kind: "Probation" | "Annual" | "AdHoc";
  reason: string | null;
  incident_id: number | null;
  period_from: string;
  period_to: string;
  /** The scheduled date a probation or annual appraisal answers */
  due_on: string | null;
  appraiser_user_id: number;
  appraiser_name: string;
  ratings: AppraisalRatingOut[];
  targets: string | null;
  overall_rating: "Outstanding" | "Good" | "Satisfactory" | "NeedsImprovement" | "Unsatisfactory" | null;
  strengths: string | null;
  development_needs: string | null;
  development_plan: string | null;
  status: "Draft" | "Signed" | "Acknowledged" | "Cancelled";
  signed_at: string | null;
  sign_stamp: AuthorStampOut | null;
  employee_comments: string | null;
  acknowledged_on: string | null;
  cancel_reason: string | null;
  created_at: string;
  row_version: number;
  /** Signed within appraisal_grace_days of due_on (MSDS HRM 137) */
  on_time: boolean | null;
  /** Training recorded against this appraisal (MSDS HRM 136 ii) */
  trainings_after: number;
}

export interface AppraisalRatingOut {
  criterion: string;
  kind: "Administrative" | "Performance";
  rating: number;
  comment?: string | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** One training of a member of staff: a session attended or an individual record. */
export interface TrainingRecordOut {
  source: "Session" | "Individual";
  /** session_id or training_id */
  id: number;
  /** The session's number */
  number: string | null;
  employee_id: number;
  title: string;
  requirement_code: string | null;
  category: "Clinical" | "Safety" | "Emergency" | "InfectionControl" | "PatientRights" | "Quality" | "Medication" | "Equipment" | "Management" | "Other";
  completed_on: string;
  hours: number | null;
  provider: string | null;
  passed: boolean | null;
  certificate_no: string | null;
  valid_until: string | null;
  appraisal_id: number | null;
}

